import torch, json
E=W('model.embed_tokens.weight'); Em=E-E.mean(0)
T=json.load(open('/work/toks.json'))
code=T['code']
eng=[]
for w in ['the','house','river','because','quickly','green','music','table','people','water','city','friend','happy','after','between','small','world','long','story','children','money','country','night','school']:
    e=encode(' '+w); 
    if len(e)==1: eng.append(e[0])
dig=T['digits']
cyr=[encode(' '+w)[0] for w in ['дом','вода','город','книга','друг','время','человек','жизнь','день','рука'] if len(encode(' '+w))==1]
print(len(eng),len(cyr))
out={}
for L in [0,1]:
    w1=W(f'model.layers.{L}.feed_forward.w1.weight'); w3=W(f'model.layers.{L}.feed_forward.w3.weight')
    n=W(f'model.layers.{L}.ffn_norm.weight')
    def act(ids):
        x=Em[ids]; x=x/x.norm(dim=1,keepdim=True)*n
        a=torch.nn.functional.silu(x@w1.T)*(x@w3.T)
        return a.abs().mean(0)
    A={k:act(v) for k,v in [('code',code),('eng',eng),('dig',dig),('cyr',cyr)]}
    for k in ['code','dig','cyr']:
        others=torch.stack([A[o] for o in A if o!=k]).max(0).values
        s=A[k]-others
        top=torch.argsort(-s)[:256]
        out[f'{L}_{k}']=top.tolist()
        print(L,k,'top sel',[round(v,3) for v in s[top[:5]].tolist()],'mean top128',round(s[top[:128]].mean().item(),3),'ratio',round((A[k][top[:128]].mean()/others[top[:128]].mean()).item(),2))
json.dump(out,open('/work/dense.json','w'))
for L in [0,1]:
    for k in ['code','dig','cyr']:
        for K in [64,128,256]:
            json.dump({'kind':'mlp_cluster','layer':L,'indices':out[f'{L}_{k}'][:K]},open(f'/work/d{L}_{k}_{K}.json','w'))
